package cn.shiguang.qwenpocket;
import android.app.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;
final class VisionWorkbench {
    final MainActivity a;final Dialog dialog;final CanvasView canvas;EditText transcript;final TextView hint;
    Bitmap bitmap;String path;boolean working=false;
    VisionWorkbench(MainActivity a,String path)throws IOException{
        this.a=a;this.path=path;bitmap=BitmapFactory.decodeFile(path);if(bitmap==null)throw new IOException("图片无法读取");dialog=new Dialog(a,android.R.style.Theme_Material_Light_NoActionBar);
        LinearLayout page=a.column();page.setPadding(a.dp(16),a.dp(16),a.dp(16),a.dp(20));page.setBackgroundColor(MainActivity.BG);
        LinearLayout head=a.row();Button back=a.button("返回",false);back.setOnClickListener(v->{if(!working)dialog.dismiss();});head.addView(back);TextView title=a.text("看图工作台",21,MainActivity.INK);title.setGravity(Gravity.CENTER);head.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button use=a.button("用于提问",true);use.setOnClickListener(v->apply());head.addView(use);page.addView(head);
        canvas=new CanvasView();page.addView(canvas,new LinearLayout.LayoutParams(-1,0,1));
        hint=a.text("双指放大 · 框选裁剪 · 由本地模型识别与分析",12,MainActivity.MUTED);page.addView(hint);
        LinearLayout modes=a.row();for(String mode:new String[]{"查看","框选","编号"}){Button b=a.button(mode,false);b.setOnClickListener(v->{canvas.mode=mode;hint.setText(mode.equals("框选")?"拖出题目区域，再点“裁剪选区”":mode.equals("编号")?"点按添加编号；仅统计你标记的点，点“撤销编号”移除最后一个":"双指放大，拖动查看");});modes.addView(b,new LinearLayout.LayoutParams(0,-2,1));}Button undo=a.button("撤销编号",false);undo.setOnClickListener(v->{if(!working&&!canvas.points.isEmpty()){canvas.points.remove(canvas.points.size()-1);canvas.invalidate();}});modes.addView(undo,new LinearLayout.LayoutParams(0,-2,1));page.addView(modes);
        LinearLayout actions=a.row();Button ocr=a.button("模型识字",false);ocr.setOnClickListener(v->recognize());actions.addView(ocr,new LinearLayout.LayoutParams(0,-2,1));Button crop=a.button("裁剪选区",false);crop.setOnClickListener(v->crop());actions.addView(crop,new LinearLayout.LayoutParams(0,-2,1));Button calculate=a.button("模型计算",false);calculate.setOnClickListener(v->askModel(1));actions.addView(calculate,new LinearLayout.LayoutParams(0,-2,1));page.addView(actions);
        transcript=new EditText(a);transcript.setTextSize(14);transcript.setHint("可补充题目条件、需要关注的位置或自己的观察，随图片交给模型。");transcript.setGravity(Gravity.TOP);transcript.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE);page.addView(transcript,new LinearLayout.LayoutParams(-1,a.dp(140)));
        dialog.setContentView(page);dialog.setOnDismissListener(d->{if(!working){bitmap.recycle();}});dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);
    }
    void show(){dialog.show();dialog.getWindow().setLayout(-1,-1);}
    void recognize(){askModel(10);}
    void askModel(int task){if(working)return;String selected=path,notes=transcript.getText().toString();dialog.dismiss();a.useTask(task,TaskExamples.taskPrompt(task),false,true,selected,notes);}
    void crop(){if(working)return;Rect r=canvas.selection();if(r.width()<20||r.height()<20){a.toast("先在框选模式拖出一个区域");return;}try{Bitmap clipped=Bitmap.createBitmap(bitmap,r.left,r.top,r.width(),r.height());File out=new File(a.getFilesDir(),"images/"+UUID.randomUUID()+".jpg");try(FileOutputStream os=new FileOutputStream(out)){clipped.compress(Bitmap.CompressFormat.JPEG,95,os);}bitmap.recycle();bitmap=clipped;path=out.getPath();canvas.points.clear();canvas.rect.setEmpty();canvas.zoom=1;canvas.panX=canvas.panY=0;transcript.setText("");canvas.invalidate();hint.setText("已裁剪，原图保留；可重新识别这一区域");}catch(Exception e){a.toast("裁剪失败："+MainActivity.friendly(e));}}
    void apply(){if(working)return;StringBuilder evidence=new StringBuilder(transcript.getText().toString().trim());if(evidence.length()>12000){a.toast("核对文字过长，请保留相关区域");return;}
        if(!canvas.points.isEmpty()){evidence.append("\n用户手动标记的参考位置，不是目标计数答案：\n");for(int i=0;i<canvas.points.size();i++){PointF p=canvas.points.get(i);evidence.append(i+1).append(": (").append((int)(p.x*1000/bitmap.getWidth())).append(',').append((int)(p.y*1000/bitmap.getHeight())).append(")\n");}}
        if(!a.pendingImage.equals(path))a.pendingEvidence="";a.pendingImage=path;a.pendingEvidence=evidence.toString();a.refreshAttachment();a.saveChat();dialog.dismiss();a.toast("已附上图片与核对记录");
    }
    final class CanvasView extends View {
        final Paint paint=new Paint(3);final Matrix matrix=new Matrix(),inverse=new Matrix();final RectF rect=new RectF();final ArrayList<PointF> points=new ArrayList<>();String mode="查看";float zoom=1,panX=0,panY=0,startX,startY,lastX,lastY;boolean moved=false;final ScaleGestureDetector pinch;
        CanvasView(){super(a);pinch=new ScaleGestureDetector(a,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScale(ScaleGestureDetector detector){zoom=Math.max(1,Math.min(6,zoom*detector.getScaleFactor()));invalidate();return true;}});setOnLongClickListener(v->{if(!points.isEmpty()){points.remove(points.size()-1);invalidate();}return true;});}
        void transform(){matrix.setRectToRect(new RectF(0,0,bitmap.getWidth(),bitmap.getHeight()),new RectF(8,8,getWidth()-8,getHeight()-8),Matrix.ScaleToFit.CENTER);matrix.postScale(zoom,zoom,getWidth()/2f,getHeight()/2f);matrix.postTranslate(panX,panY);matrix.invert(inverse);}
        PointF image(float x,float y){float[] p={x,y};inverse.mapPoints(p);return new PointF(Math.max(0,Math.min(bitmap.getWidth(),p[0])),Math.max(0,Math.min(bitmap.getHeight(),p[1])));}
        Rect selection(){return new Rect(Math.max(0,(int)Math.min(rect.left,rect.right)),Math.max(0,(int)Math.min(rect.top,rect.bottom)),Math.min(bitmap.getWidth(),(int)Math.max(rect.left,rect.right)),Math.min(bitmap.getHeight(),(int)Math.max(rect.top,rect.bottom)));}
        @Override protected void onDraw(Canvas c){super.onDraw(c);transform();c.drawBitmap(bitmap,matrix,paint);paint.setStrokeWidth(a.dp(1));paint.setTextSize(a.dp(12));if(!rect.isEmpty()||rect.left!=rect.right){RectF r=new RectF(selection());matrix.mapRect(r);paint.setColor(0xff16a085);paint.setStyle(Paint.Style.STROKE);c.drawRect(r,paint);paint.setStyle(Paint.Style.FILL);}for(int i=0;i<points.size();i++){float[] p={points.get(i).x,points.get(i).y};matrix.mapPoints(p);paint.setColor(0xff236b58);c.drawCircle(p[0],p[1],a.dp(11),paint);paint.setColor(Color.WHITE);c.drawText(String.valueOf(i+1),p[0]-a.dp(4),p[1]+a.dp(4),paint);}}
        @Override public boolean onTouchEvent(android.view.MotionEvent e){if(working)return true;pinch.onTouchEvent(e);if(e.getPointerCount()>1)return true;PointF p=image(e.getX(),e.getY());if(e.getAction()==MotionEvent.ACTION_DOWN){startX=p.x;startY=p.y;lastX=e.getX();lastY=e.getY();moved=false;return true;}if(e.getAction()==MotionEvent.ACTION_MOVE){if(Math.abs(e.getX()-lastX)+Math.abs(e.getY()-lastY)>3)moved=true;if(mode.equals("框选")){rect.set(startX,startY,p.x,p.y);}else if(mode.equals("查看")&&moved){panX+=e.getX()-lastX;panY+=e.getY()-lastY;}lastX=e.getX();lastY=e.getY();invalidate();return true;}if(e.getAction()==MotionEvent.ACTION_UP){if(!moved&&mode.equals("编号")){if(points.size()<200)points.add(p);hint.setText("已编号 "+points.size()+" 个点 · 可撤销最后一个");}invalidate();performClick();return true;}return true;}
        @Override public boolean performClick(){super.performClick();return true;}
    }
}
